package raft

import (
	"encoding/json"
	"fmt"
	"runtime"
	"sort"
	"strings"
	"testing"
	"time"
)

// TestAssuranceStaleConfigurationCommitQuorum
//
// Sourced question (gap 98ee8dfd5fac4b84915f91ed4b094bcf-gap-1): after a node restarts
// with Config.RestoreCommittedLogs enabled, can the older configuration it recovers
// decide a commit that the committed configuration would not allow?
//
// Design: three voters A, B, C. A snapshots while {A,B,C} is committed, C is then removed
// (committed {A,B}) and further entries are committed. A restarts with the flag on, so
// its tracked configuration is the snapshot's {A,B,C}, and B is partitioned while C stays
// connected. A's majority then counts C, which the committed configuration no longer
// contains.

type assuranceMultiEvent map[string]interface{}

func assuranceMultiEmit(ev assuranceMultiEvent) {
	b, err := json.Marshal(ev)
	if err != nil {
		fmt.Println(`CA_EVENT {"event":"assurance.multi_marshal_error"}`)
		return
	}
	fmt.Println("CA_EVENT " + string(b))
}

type assuranceMultiNode struct {
	name   string
	id     ServerID
	addr   ServerAddress
	trans  *InmemTransport
	logs   *InmemCommitTrackingStore
	stable *InmemStore
	snaps  *InmemSnapshotStore
	fsm    *MockFSM
	conf   *Config
	raft   *Raft
}

func assuranceMultiNewNode(t *testing.T, name string) *assuranceMultiNode {
	t.Helper()
	addr, trans := NewInmemTransport("")
	conf := inmemConfig(t)
	conf.RestoreCommittedLogs = true
	conf.LocalID = ServerID("server-" + string(addr))
	return &assuranceMultiNode{
		name:   name,
		id:     ServerID("server-" + string(addr)),
		addr:   addr,
		trans:  trans,
		logs:   NewInmemCommitTrackingStore(),
		stable: NewInmemStore(),
		snaps:  NewInmemSnapshotStore(),
		fsm:    &MockFSM{},
		conf:   conf,
	}
}

func assuranceMultiConfig(nodes []*assuranceMultiNode) Configuration {
	var c Configuration
	for _, n := range nodes {
		c.Servers = append(c.Servers, Server{Suffrage: Voter, ID: n.id, Address: n.addr})
	}
	return c
}

func assuranceMultiWire(nodes []*assuranceMultiNode) {
	for i, a := range nodes {
		for j, b := range nodes {
			if i == j {
				continue
			}
			a.trans.Connect(b.addr, b.trans)
		}
	}
}

func assuranceMultiLeader(nodes []*assuranceMultiNode, timeout time.Duration) *assuranceMultiNode {
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		for _, n := range nodes {
			if n.raft != nil && n.raft.State() == Leader {
				return n
			}
		}
		time.Sleep(5 * time.Millisecond)
	}
	return nil
}

func assuranceMultiWaitLeader(n *assuranceMultiNode, timeout time.Duration) bool {
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		if n.raft.State() == Leader {
			return true
		}
		time.Sleep(5 * time.Millisecond)
	}
	return n.raft.State() == Leader
}

func assuranceMultiWaitNode(r *Raft, timeout time.Duration) bool {
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		if r.State() == Leader {
			return true
		}
		time.Sleep(5 * time.Millisecond)
	}
	return r.State() == Leader
}

func assuranceMultiConfigurations(r *Raft) configurations {
	fut := &configurationsFuture{}
	fut.ShutdownCh = r.shutdownCh
	fut.init()
	select {
	case r.configurationsCh <- fut:
	case <-r.shutdownCh:
		return configurations{}
	}
	if err := fut.Error(); err != nil {
		return configurations{}
	}
	return fut.configurations
}

func assuranceMultiSortedIDs(c Configuration) string {
	out := make([]string, 0, len(c.Servers))
	for _, s := range c.Servers {
		out = append(out, string(s.ID))
	}
	sort.Strings(out)
	return strings.Join(out, ",")
}

func assuranceMultiVoters(c Configuration) int {
	v := 0
	for _, s := range c.Servers {
		if s.Suffrage == Voter {
			v++
		}
	}
	return v
}

func assuranceMultiStackExcerpt(text string, marker string) (string, int) {
	count := strings.Count(text, marker)
	if count == 0 {
		return "", 0
	}
	idx := strings.Index(text, marker)
	start := idx - 200
	if start < 0 {
		start = 0
	}
	end := idx + 300
	if end > len(text) {
		end = len(text)
	}
	return strings.ReplaceAll(text[start:end], "\n", " | "), count
}

func assuranceMultiWaitFSMCommand(n *assuranceMultiNode, timeout time.Duration) bool {
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		if len(n.fsm.Logs()) > 0 {
			return true
		}
		time.Sleep(5 * time.Millisecond)
	}
	return len(n.fsm.Logs()) > 0
}

func assuranceMultiLastIndex(n *assuranceMultiNode) uint64 {
	idx, err := n.logs.LastIndex()
	if err != nil {
		return 0
	}
	return idx
}

// assuranceMultiLogConfig finds the newest configuration entry at or below limit.
func assuranceMultiLogConfig(logs *InmemCommitTrackingStore, limit uint64) (uint64, int, string) {
	var idx uint64
	var voters int
	var ids string
	for i := uint64(1); i <= limit; i++ {
		var entry Log
		if err := logs.GetLog(i, &entry); err != nil {
			return idx, voters, ids
		}
		if entry.Type == LogConfiguration {
			c := DecodeConfiguration(entry.Data)
			idx, voters, ids = i, assuranceMultiVoters(c), assuranceMultiSortedIDs(c)
		}
	}
	return idx, voters, ids
}

func TestAssuranceStaleConfigurationCommitQuorum(t *testing.T) {
	a := assuranceMultiNewNode(t, "A")
	b := assuranceMultiNewNode(t, "B")
	c := assuranceMultiNewNode(t, "C")
	nodes := []*assuranceMultiNode{a, b, c}
	configuration := assuranceMultiConfig(nodes)

	assuranceMultiWire(nodes)
	for _, n := range nodes {
		if err := BootstrapCluster(n.conf, n.logs, n.stable, n.snaps, n.trans, configuration); err != nil {
			t.Fatalf("bootstrap %s failed: %v", n.name, err)
		}
		r, err := NewRaft(n.conf, n.fsm, n.logs, n.stable, n.snaps, n.trans)
		if err != nil {
			t.Fatalf("NewRaft %s failed: %v", n.name, err)
		}
		n.raft = r
		// Shut every node down on any exit path: raft goroutines log through the test
		// logger, and a log after the test returns panics the test binary.
		defer func(r *Raft) { _ = r.Shutdown().Error() }(r)
	}

	leader := assuranceMultiLeader(nodes, 5*time.Second)
	if leader == nil {
		t.Fatalf("no leader was elected")
	}
	assuranceMultiEmit(assuranceMultiEvent{
		"event":          "assurance.multi.start",
		"leader":         leader.name,
		"a_id":           string(a.id),
		"b_id":           string(b.id),
		"c_id":           string(c.id),
		"configured_ids": assuranceMultiSortedIDs(configuration),
	})

	// Make A the leader through a real leadership transfer so that the rest of the case is
	// deterministic: the node that is removed must not be the leader, and the node that is
	// restarted must have applied entries before it can snapshot.
	if leader != a {
		if err := leader.raft.LeadershipTransferToServer(a.id, a.addr).Error(); err != nil {
			t.Fatalf("leadership transfer to A failed: %v", err)
		}
	}
	if !assuranceMultiWaitNode(a.raft, 5*time.Second) {
		t.Fatalf("A did not become leader after transfer")
	}
	leader = a

	// Commit one command through A and wait until A's FSM has applied it: a plain FSM
	// receives only command entries, and runFSM refuses a snapshot request while its own
	// last applied index is still zero (ErrNothingNewToSnapshot).
	if err := leader.raft.Apply([]byte("before-snapshot"), 2*time.Second).Error(); err != nil {
		t.Fatalf("pre-snapshot apply failed: %v", err)
	}
	if !assuranceMultiWaitFSMCommand(a, 3*time.Second) {
		t.Fatalf("A's FSM applied no command before the snapshot request")
	}

	// Snapshot A while {A,B,C} is still the committed configuration.
	if err := a.raft.Snapshot().Error(); err != nil {
		t.Fatalf("snapshot on A failed: %v", err)
	}
	snapIndex, snapTerm := a.raft.getLastSnapshot()
	assuranceMultiEmit(assuranceMultiEvent{
		"event":          "assurance.multi.snapshot",
		"node":           "A",
		"snapshot_index": snapIndex,
		"snapshot_term":  snapTerm,
	})

	// Remove C, which commits against {A,B}, then commit more entries.
	if err := leader.raft.RemoveServer(c.id, 0, 2*time.Second).Error(); err != nil {
		t.Fatalf("RemoveServer(C) failed: %v", err)
	}
	for i := 0; i < 3; i++ {
		if err := leader.raft.Apply([]byte(fmt.Sprintf("after-remove-%d", i)), 2*time.Second).Error(); err != nil {
			t.Fatalf("post-removal apply %d failed: %v", i, err)
		}
	}
	aStaged, _ := a.logs.GetCommitIndex()
	aLast := assuranceMultiLastIndex(a)
	removeIndex, removeVoters, removeIDs := assuranceMultiLogConfig(a.logs, aLast)
	assuranceMultiEmit(assuranceMultiEvent{
		"event":                 "assurance.multi.removed",
		"removed_id":            string(c.id),
		"log_config_index":      removeIndex,
		"log_config_voters":     removeVoters,
		"log_config_ids":        removeIDs,
		"a_log_last_index":      aLast,
		"a_staged_commit_index": aStaged,
		"leader_after_removal":  leader.name,
	})

	// Restart A with the flag on, over the same stores, and partition B from A and C.
	if err := a.raft.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown A failed: %v", err)
	}
	b.trans.Disconnect(a.addr)
	b.trans.Disconnect(c.addr)
	c.trans.Disconnect(b.addr)

	_, newTrans := NewInmemTransport(a.addr)
	newTrans.Connect(c.addr, c.trans)
	c.trans.Connect(a.addr, newTrans)
	newTrans.Disconnect(b.addr)

	confA := *a.conf
	confA.RestoreCommittedLogs = true
	restartedFSM := &MockFSM{}
	restarted, err := NewRaft(&confA, restartedFSM, a.logs, a.stable, a.snaps, newTrans)
	if err != nil {
		t.Fatalf("restart of A failed: %v", err)
	}
	defer func() { _ = restarted.Shutdown().Error() }()
	a.raft = restarted
	a.trans = newTrans

	confs := assuranceMultiConfigurations(restarted)
	assuranceMultiEmit(assuranceMultiEvent{
		"event":                  "assurance.multi.restart",
		"node":                   "A",
		"latest_config_index":    confs.latestIndex,
		"latest_config_voters":   assuranceMultiVoters(confs.latest),
		"latest_config_ids":      assuranceMultiSortedIDs(confs.latest),
		"committed_config_index": confs.committedIndex,
		"log_config_index":       removeIndex,
		"log_config_voters":      removeVoters,
		"log_config_ids":         removeIDs,
		"b_connected":            false,
		"c_connected":            true,
		"b_last_index":           assuranceMultiLastIndex(b),
		"c_last_index":           assuranceMultiLastIndex(c),
	})

	wonLeadership := assuranceMultiWaitNode(restarted, 5*time.Second)
	outcome := assuranceMultiEvent{
		"event":                   "assurance.multi.outcome",
		"a_became_leader":         wonLeadership,
		"a_tracked_voters":        assuranceMultiVoters(confs.latest),
		"a_tracked_ids":           assuranceMultiSortedIDs(confs.latest),
		"committed_config_voters": removeVoters,
		"committed_config_ids":    removeIDs,
		"b_connected":             false,
	}

	if wonLeadership {
		payload := []byte("stale-quorum-entry")
		future := restarted.Apply(payload, 2*time.Second)
		applyErr := future.Error()
		entryIndex := future.Index()
		time.Sleep(200 * time.Millisecond)

		var stored Log
		var entryTerm uint64
		if err := a.logs.GetLog(entryIndex, &stored); err == nil {
			entryTerm = stored.Term
		}
		var bEntry Log
		bHasEntry := b.logs.GetLog(entryIndex, &bEntry) == nil
		var cEntry Log
		cHasEntry := c.logs.GetLog(entryIndex, &cEntry) == nil

		applied := false
		for _, l := range restartedFSM.Logs() {
			if string(l) == string(payload) {
				applied = true
				break
			}
		}

		outcome["entry_index"] = entryIndex
		outcome["entry_term"] = entryTerm
		outcome["apply_error"] = applyErr
		outcome["a_commit_index"] = restarted.CommitIndex()
		outcome["a_applied_index"] = restarted.AppliedIndex()
		outcome["b_log_has_entry"] = bHasEntry
		outcome["c_log_has_entry"] = cHasEntry
		outcome["c_entry_term"] = cEntry.Term
		outcome["a_fsm_applied_payload"] = applied
		outcome["committed_config_majority_lacks_entry"] = applyErr == nil && entryTerm != 0 && !bHasEntry
	}
	assuranceMultiEmit(outcome)

	// Stop the restarted node before the test returns so nothing logs afterwards.
	_ = restarted.Shutdown().Error()
}

// TestAssuranceRecoveredSnapshotConfiguration
//
// Sourced question: when a node restarts with Config.RestoreCommittedLogs enabled and
// recovers no configuration, does that missing configuration reach durable state? A node
// whose tracked committed configuration is empty will write that empty configuration and
// its index into the snapshot metadata it creates, and a later restart restores the
// configuration from that snapshot, so the loss outlives the replay path that produced it.
func TestAssuranceRecoveredSnapshotConfiguration(t *testing.T) {
	a := assuranceMultiNewNode(t, "A")
	b := assuranceMultiNewNode(t, "B")
	c := assuranceMultiNewNode(t, "C")
	nodes := []*assuranceMultiNode{a, b, c}
	configuration := assuranceMultiConfig(nodes)

	assuranceMultiWire(nodes)
	for _, n := range nodes {
		if err := BootstrapCluster(n.conf, n.logs, n.stable, n.snaps, n.trans, configuration); err != nil {
			t.Fatalf("bootstrap %s failed: %v", n.name, err)
		}
		r, err := NewRaft(n.conf, n.fsm, n.logs, n.stable, n.snaps, n.trans)
		if err != nil {
			t.Fatalf("NewRaft %s failed: %v", n.name, err)
		}
		n.raft = r
		defer func(r *Raft) { _ = r.Shutdown().Error() }(r)
	}

	leader := assuranceMultiLeader(nodes, 5*time.Second)
	if leader == nil {
		t.Fatalf("no leader was elected")
	}
	if leader == a {
		if err := a.raft.LeadershipTransferToServer(b.id, b.addr).Error(); err != nil {
			t.Fatalf("leadership transfer to B failed: %v", err)
		}
		if !assuranceMultiWaitNode(b.raft, 5*time.Second) {
			t.Fatalf("B did not become leader after transfer")
		}
		leader = b
	}
	assuranceMultiEmit(assuranceMultiEvent{
		"event":          "assurance.recovsnap.start",
		"leader":         leader.name,
		"configured_ids": assuranceMultiSortedIDs(configuration),
	})

	// Give A a command to apply, then restart it with the flag on.
	if err := leader.raft.Apply([]byte("before-restart"), 2*time.Second).Error(); err != nil {
		t.Fatalf("pre-restart apply failed: %v", err)
	}
	if !assuranceMultiWaitFSMCommand(a, 3*time.Second) {
		t.Fatalf("A's FSM applied no command before the restart")
	}
	if err := a.raft.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown A failed: %v", err)
	}
	_, trans1 := NewInmemTransport(a.addr)
	trans1.Connect(b.addr, b.trans)
	trans1.Connect(c.addr, c.trans)
	b.trans.Connect(a.addr, trans1)
	c.trans.Connect(a.addr, trans1)
	a.trans = trans1

	confA := *a.conf
	confA.RestoreCommittedLogs = true
	fsmA := &MockFSM{}
	restarted, err := NewRaft(&confA, fsmA, a.logs, a.stable, a.snaps, trans1)
	if err != nil {
		t.Fatalf("flag-on restart of A failed: %v", err)
	}
	a.raft = restarted
	a.fsm = fsmA
	defer func() { _ = restarted.Shutdown().Error() }()

	staged, _ := a.logs.GetCommitIndex()
	aLast := assuranceMultiLastIndex(a)
	logConfigIndex, logConfigVoters, logConfigIDs := assuranceMultiLogConfig(a.logs, aLast)
	confs := assuranceMultiConfigurations(restarted)
	assuranceMultiEmit(assuranceMultiEvent{
		"event":                   "assurance.recovsnap.flag_on_restart",
		"node":                    "A",
		"restore_committed_logs":  true,
		"snapshot_index":          0,
		"staged_commit_index":     staged,
		"a_log_last_index":        aLast,
		"log_config_index":        logConfigIndex,
		"log_config_voters":       logConfigVoters,
		"log_config_ids":          logConfigIDs,
		"latest_config_index":     confs.latestIndex,
		"latest_config_voters":    assuranceMultiVoters(confs.latest),
		"latest_config_ids":       assuranceMultiSortedIDs(confs.latest),
		"committed_config_index":  confs.committedIndex,
		"committed_config_voters": assuranceMultiVoters(confs.committed),
	})

	// Commit one more command and wait until A's FSM has applied it: runFSM refuses a
	// snapshot request while its own last applied index is zero, and the replayed range may
	// contain only configuration and no-op entries for a plain FSM.
	if err := leader.raft.Apply([]byte("after-restart"), 2*time.Second).Error(); err != nil {
		t.Fatalf("post-restart apply failed: %v", err)
	}
	if !assuranceMultiWaitFSMCommand(a, 3*time.Second) {
		t.Fatalf("A's FSM applied no command after the restart")
	}

	// A takes a snapshot through the normal path and the harness reads its metadata.
	if err := restarted.Snapshot().Error(); err != nil {
		t.Fatalf("snapshot on A failed: %v", err)
	}
	snaps, err := a.snaps.List()
	if err != nil || len(snaps) == 0 {
		t.Fatalf("no snapshot metadata on A: %v", err)
	}
	meta := snaps[0]
	snapVoters := assuranceMultiVoters(meta.Configuration)
	snapIDs := assuranceMultiSortedIDs(meta.Configuration)
	snapshotMatchesLogConfig := meta.ConfigurationIndex == logConfigIndex &&
		snapVoters == logConfigVoters && snapIDs == logConfigIDs
	assuranceMultiEmit(assuranceMultiEvent{
		"event":                              "assurance.recovsnap.snapshot",
		"node":                               "A",
		"restore_committed_logs":             true,
		"snapshot_index":                     meta.Index,
		"snapshot_config_index":              meta.ConfigurationIndex,
		"snapshot_config_voters":             snapVoters,
		"snapshot_config_ids":                snapIDs,
		"log_config_index":                   logConfigIndex,
		"log_config_voters":                  logConfigVoters,
		"log_config_ids":                     logConfigIDs,
		"snapshot_config_matches_log_config": snapshotMatchesLogConfig,
	})

	// Restart A again, this time with the replay disabled: the configuration now comes from
	// the snapshot the node itself wrote.
	if err := restarted.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown of restarted A failed: %v", err)
	}
	_, trans2 := NewInmemTransport(a.addr)
	trans2.Connect(b.addr, b.trans)
	trans2.Connect(c.addr, c.trans)
	b.trans.Connect(a.addr, trans2)
	c.trans.Connect(a.addr, trans2)
	a.trans = trans2

	confA2 := *a.conf
	confA2.RestoreCommittedLogs = false
	fsmA2 := &MockFSM{}
	restarted2, err := NewRaft(&confA2, fsmA2, a.logs, a.stable, a.snaps, trans2)
	if err != nil {
		t.Fatalf("flag-off restart of A failed: %v", err)
	}
	a.raft = restarted2
	a.fsm = fsmA2
	defer func() { _ = restarted2.Shutdown().Error() }()

	confs2 := assuranceMultiConfigurations(restarted2)
	leaderObserved := assuranceMultiWaitNode(restarted2, 1500*time.Millisecond)
	snapIndex2, _ := restarted2.getLastSnapshot()
	assuranceMultiEmit(assuranceMultiEvent{
		"event":                               "assurance.recovsnap.flag_off_restart",
		"node":                                "A",
		"restore_committed_logs":              false,
		"restored_snapshot_index":             snapIndex2,
		"latest_config_index":                 confs2.latestIndex,
		"latest_config_voters":                assuranceMultiVoters(confs2.latest),
		"latest_config_ids":                   assuranceMultiSortedIDs(confs2.latest),
		"committed_config_index":              confs2.committedIndex,
		"log_config_index":                    logConfigIndex,
		"log_config_voters":                   logConfigVoters,
		"log_config_ids":                      logConfigIDs,
		"leader_observed":                     leaderObserved,
		"final_state":                         restarted2.State().String(),
		"empty_config_after_flag_off_restart": assuranceMultiVoters(confs2.latest) == 0,
	})

	_ = restarted2.Shutdown().Error()
}

// TestAssuranceReplayBlockedMemberAvailability
//
// Sourced question: what does a member that cannot start cost the cluster? A node whose
// startup replay exceeds the FSM channel's capacity never returns from NewRaft, so it
// never participates, and the group runs with one member fewer. This harness builds a
// three-voter cluster whose committed log is far above any snapshot, restarts one member
// with and without the replay, and then stops one more member: with the replay (which
// blocks) the surviving pair cannot commit, without it the surviving pair still can.
func assuranceRunAvailabilityCase(t *testing.T, caseName string, restoreCommittedLogs bool, commands int, maxAppendEntries int) {
	t.Helper()

	a := assuranceMultiNewNode(t, "A")
	b := assuranceMultiNewNode(t, "B")
	c := assuranceMultiNewNode(t, "C")
	nodes := []*assuranceMultiNode{a, b, c}
	configuration := assuranceMultiConfig(nodes)
	for _, n := range nodes {
		n.conf.MaxAppendEntries = maxAppendEntries
		// Keep the whole committed log above the snapshot so the restart has a large replay.
		n.conf.SnapshotThreshold = 1 << 30
		n.conf.SnapshotInterval = time.Hour
	}

	assuranceMultiWire(nodes)
	for _, n := range nodes {
		if err := BootstrapCluster(n.conf, n.logs, n.stable, n.snaps, n.trans, configuration); err != nil {
			t.Fatalf("bootstrap %s failed: %v", n.name, err)
		}
		r, err := NewRaft(n.conf, n.fsm, n.logs, n.stable, n.snaps, n.trans)
		if err != nil {
			t.Fatalf("NewRaft %s failed: %v", n.name, err)
		}
		n.raft = r
	}
	leader := assuranceMultiLeader(nodes, 5*time.Second)
	if leader == nil {
		t.Fatalf("no leader was elected")
	}
	for _, n := range nodes {
		if n != leader {
			defer func(r *Raft) { _ = r.Shutdown().Error() }(n.raft)
		}
	}
	defer func(r *Raft) { _ = r.Shutdown().Error() }(leader.raft)

	if leader == a {
		target := b
		if err := a.raft.LeadershipTransferToServer(target.id, target.addr).Error(); err != nil {
			t.Fatalf("leadership transfer away from A failed: %v", err)
		}
		if !assuranceMultiWaitNode(target.raft, 5*time.Second) {
			t.Fatalf("transfer target did not become leader")
		}
		leader = target
	}

	for i := 0; i < commands; i++ {
		if err := leader.raft.Apply([]byte("filler"), 5*time.Second).Error(); err != nil {
			t.Fatalf("filler apply %d failed: %v", i, err)
		}
	}
	staged, _ := a.logs.GetCommitIndex()
	aLast := assuranceMultiLastIndex(a)
	snapA, _ := a.raft.getLastSnapshot()
	a.fsm = &MockFSM{}
	assuranceMultiEmit(assuranceMultiEvent{
		"event":                 "assurance.availability.prefix",
		"case":                  caseName,
		"leader":                leader.name,
		"commands":              commands,
		"max_append_entries":    maxAppendEntries,
		"a_staged_commit_index": staged,
		"a_log_last_index":      aLast,
		"a_snapshot_index":      snapA,
		"replay_batches":        (staged - snapA + uint64(maxAppendEntries) - 1) / uint64(maxAppendEntries),
	})

	// Restart A over its own stores with the case's replay setting.
	if err := a.raft.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown A failed: %v", err)
	}
	_, newTrans := NewInmemTransport(a.addr)
	newTrans.Connect(b.addr, b.trans)
	newTrans.Connect(c.addr, c.trans)
	b.trans.Connect(a.addr, newTrans)
	c.trans.Connect(a.addr, newTrans)
	a.trans = newTrans

	confA := *a.conf
	confA.RestoreCommittedLogs = restoreCommittedLogs
	type restartResult struct {
		raft     *Raft
		err      error
		returned bool
		elapsed  int64
	}
	ch := make(chan restartResult, 1)
	go func() {
		start := time.Now()
		r, err := NewRaft(&confA, a.fsm, a.logs, a.stable, a.snaps, newTrans)
		ch <- restartResult{raft: r, err: err, returned: true, elapsed: time.Since(start).Milliseconds()}
	}()
	const waitMS = 8000
	var res restartResult
	select {
	case res = <-ch:
	case <-time.After(waitMS * time.Millisecond):
	}
	excerpt, mentions := "", 0
	if !res.returned {
		buf := make([]byte, 1<<20)
		n := runtime.Stack(buf, true)
		excerpt, mentions = assuranceMultiStackExcerpt(string(buf[:n]), "restoreFromCommittedLogs")
	}
	assuranceMultiEmit(assuranceMultiEvent{
		"event":                  "assurance.availability.restart." + caseName,
		"case":                   caseName,
		"node":                   "A",
		"restore_committed_logs": restoreCommittedLogs,
		"max_append_entries":     maxAppendEntries,
		"replay_entries":         staged,
		"new_raft_returned":      res.returned,
		"elapsed_ms":             res.elapsed,
		"wait_ms":                waitMS,
		"stack_mentions":         mentions,
	})
	if res.returned && res.raft != nil {
		defer func() { _ = res.raft.Shutdown().Error() }()
	}

	// With two members live the group should still commit.
	commitWhileTwoLive := leader.raft.Apply([]byte("while-two-live"), 3*time.Second).Error()

	// Stop the member that is neither the leader nor A: the surviving pair is {leader, A}
	// when A is running, and {leader} when A never started.
	stopped := b
	if leader == b {
		stopped = c
	}
	if stopped == a {
		t.Fatalf("refusing to stop the restarted node")
	}
	stopErr := stopped.raft.Shutdown().Error()
	commitAfterStop := leader.raft.Apply([]byte("after-stop"), 3*time.Second).Error()

	outcome := assuranceMultiEvent{
		"event":                    "assurance.availability.outcome." + caseName,
		"case":                     caseName,
		"node":                     "A",
		"restore_committed_logs":   restoreCommittedLogs,
		"a_new_raft_returned":      res.returned,
		"stopped_node":             stopped.name,
		"stop_error":               fmt.Sprint(stopErr),
		"commit_while_two_live_ok": commitWhileTwoLive == nil,
		"commit_after_stop_ok":     commitAfterStop == nil,
		"commit_after_stop_error":  fmt.Sprint(commitAfterStop),
		"stack_mentions_on_block":  mentions,
		"blocked_stack_excerpt":    excerpt,
	}
	assuranceMultiEmit(outcome)
	if res.returned && res.raft != nil {
		_ = res.raft.Shutdown().Error()
	}
}

func TestAssuranceReplayBlockedMemberAvailability(t *testing.T) {
	const commands = 3000
	const maxAppendEntries = 16 // bound: 128 * 16 = 2048 replayed entries
	assuranceRunAvailabilityCase(t, "replay_on", true, commands, maxAppendEntries)
	assuranceRunAvailabilityCase(t, "replay_off", false, commands, maxAppendEntries)
	// Same flag-on case at the library's default batch size, where the bound is 128 * 64 = 8192
	// replayed entries: the consequence should not depend on the smaller batch size above.
	assuranceRunAvailabilityCase(t, "replay_on_default_batch", true, 9000, 64)
}

// TestAssuranceRecoveredVoterAuthorityAttempt
//
// Sourced question: in a multi-node group, does a voter that recovers without a
// configuration still attempt to acquire authority when it is needed? A node whose
// tracked configuration is empty refuses to start an election at all, so it is a voter
// that can never become a candidate; the same node with the same log and the replay
// disabled recovers its configuration and does attempt one.
func assuranceRunAuthorityCase(t *testing.T, caseName string, restoreCommittedLogs bool) {
	t.Helper()

	a := assuranceMultiNewNode(t, "A")
	b := assuranceMultiNewNode(t, "B")
	c := assuranceMultiNewNode(t, "C")
	nodes := []*assuranceMultiNode{a, b, c}
	configuration := assuranceMultiConfig(nodes)

	assuranceMultiWire(nodes)
	for _, n := range nodes {
		if err := BootstrapCluster(n.conf, n.logs, n.stable, n.snaps, n.trans, configuration); err != nil {
			t.Fatalf("bootstrap %s failed: %v", n.name, err)
		}
		r, err := NewRaft(n.conf, n.fsm, n.logs, n.stable, n.snaps, n.trans)
		if err != nil {
			t.Fatalf("NewRaft %s failed: %v", n.name, err)
		}
		n.raft = r
	}
	leader := assuranceMultiLeader(nodes, 5*time.Second)
	if leader == nil {
		t.Fatalf("no leader was elected")
	}
	for i := 0; i < 3; i++ {
		if err := leader.raft.Apply([]byte("filler"), 3*time.Second).Error(); err != nil {
			t.Fatalf("filler apply %d failed: %v", i, err)
		}
	}
	// The case needs A's persisted commit index to be non-zero, otherwise the startup scan
	// runs from index 1, processes the configuration entry and A recovers a configuration;
	// keep committing until A's store reports one.
	staged, _ := a.logs.GetCommitIndex()
	extra := 0
	for staged == 0 && extra < 20 {
		if err := leader.raft.Apply([]byte("premise-filler"), 3*time.Second).Error(); err != nil {
			t.Fatalf("premise filler apply %d failed: %v", extra, err)
		}
		extra++
		time.Sleep(10 * time.Millisecond)
		staged, _ = a.logs.GetCommitIndex()
	}
	if staged == 0 {
		t.Fatalf("A's persisted commit index never advanced above zero")
	}
	if err := a.raft.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown A failed: %v", err)
	}

	_, newTrans := NewInmemTransport(a.addr)
	newTrans.Connect(b.addr, b.trans)
	newTrans.Connect(c.addr, c.trans)
	b.trans.Connect(a.addr, newTrans)
	c.trans.Connect(a.addr, newTrans)
	a.trans = newTrans

	confA := *a.conf
	confA.RestoreCommittedLogs = restoreCommittedLogs
	restartedFSM := &MockFSM{}
	restarted, err := NewRaft(&confA, restartedFSM, a.logs, a.stable, a.snaps, newTrans)
	if err != nil {
		t.Fatalf("restart of A failed: %v", err)
	}
	a.raft = restarted
	a.fsm = restartedFSM
	defer func() { _ = restarted.Shutdown().Error() }()

	confs := assuranceMultiConfigurations(restarted)
	assuranceMultiEmit(assuranceMultiEvent{
		"event":                  "assurance.authority.restart." + caseName,
		"case":                   caseName,
		"node":                   "A",
		"restore_committed_logs": restoreCommittedLogs,
		"staged_commit_index":    staged,
		"premise_filler_applies": extra,
		"latest_config_index":    confs.latestIndex,
		"latest_config_voters":   assuranceMultiVoters(confs.latest),
		"latest_config_ids":      assuranceMultiSortedIDs(confs.latest),
	})

	// Take away every other voter so that A is the only member left.
	if err := b.raft.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown B failed: %v", err)
	}
	if err := c.raft.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown C failed: %v", err)
	}

	// Sample the states the sole surviving voter passes through.
	seen := map[string]int{}
	deadline := time.Now().Add(1500 * time.Millisecond)
	for time.Now().Before(deadline) {
		seen[restarted.State().String()]++
		time.Sleep(5 * time.Millisecond)
	}
	_, _ = fmt.Sscanf("", "")
	samples := 0
	for _, n := range seen {
		samples += n
	}
	assuranceMultiEmit(assuranceMultiEvent{
		"event":                   "assurance.authority.attempt." + caseName,
		"case":                    caseName,
		"node":                    "A",
		"restore_committed_logs":  restoreCommittedLogs,
		"samples":                 samples,
		"follower_samples":        seen["Follower"],
		"candidate_samples":       seen["Candidate"],
		"leader_samples":          seen["Leader"],
		"attempted_candidacy":     seen["Candidate"] > 0,
		"observed_snapshot_index": func() uint64 { i, _ := restarted.getLastSnapshot(); return i }(),
		"final_state":             restarted.State().String(),
	})
}

func TestAssuranceRecoveredVoterAuthorityAttempt(t *testing.T) {
	assuranceRunAuthorityCase(t, "empty_config", true)
	assuranceRunAuthorityCase(t, "recovered_config", false)
}

// TestAssuranceEmptyConfigVoterStillVotes
//
// Sourced question: does a voter that recovers without a configuration still support a
// healthy peer's candidacy, even though it never becomes a candidate itself? Vote
// admission checks membership only when the tracked configuration is non-empty, so the
// defective node may still grant a vote; this harness puts a two-voter group in exactly
// that position and observes whether the healthy peer can be elected with its vote.
func TestAssuranceEmptyConfigVoterStillVotes(t *testing.T) {
	a := assuranceMultiNewNode(t, "A")
	b := assuranceMultiNewNode(t, "B")
	nodes := []*assuranceMultiNode{a, b}
	configuration := assuranceMultiConfig(nodes)

	assuranceMultiWire(nodes)
	for _, n := range nodes {
		if err := BootstrapCluster(n.conf, n.logs, n.stable, n.snaps, n.trans, configuration); err != nil {
			t.Fatalf("bootstrap %s failed: %v", n.name, err)
		}
		r, err := NewRaft(n.conf, n.fsm, n.logs, n.stable, n.snaps, n.trans)
		if err != nil {
			t.Fatalf("NewRaft %s failed: %v", n.name, err)
		}
		n.raft = r
	}
	leader := assuranceMultiLeader(nodes, 5*time.Second)
	if leader == nil {
		t.Fatalf("no leader was elected")
	}
	if leader != b {
		if err := leader.raft.LeadershipTransferToServer(b.id, b.addr).Error(); err != nil {
			t.Fatalf("leadership transfer to B failed: %v", err)
		}
		if !assuranceMultiWaitNode(b.raft, 5*time.Second) {
			t.Fatalf("B did not become leader after transfer")
		}
	}

	for i := 0; i < 3; i++ {
		if err := b.raft.Apply([]byte("filler"), 3*time.Second).Error(); err != nil {
			t.Fatalf("filler apply %d failed: %v", i, err)
		}
	}
	staged, _ := a.logs.GetCommitIndex()
	extra := 0
	for staged == 0 && extra < 20 {
		if err := b.raft.Apply([]byte("premise-filler"), 3*time.Second).Error(); err != nil {
			t.Fatalf("premise filler apply %d failed: %v", extra, err)
		}
		extra++
		time.Sleep(10 * time.Millisecond)
		staged, _ = a.logs.GetCommitIndex()
	}
	if staged == 0 {
		t.Fatalf("A's persisted commit index never advanced above zero")
	}

	// Restart A with the replay enabled: with a non-zero persisted commit index its startup
	// scan is skipped and it tracks no configuration at all.
	if err := a.raft.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown A failed: %v", err)
	}
	_, transA := NewInmemTransport(a.addr)
	transA.Connect(b.addr, b.trans)
	b.trans.Connect(a.addr, transA)
	a.trans = transA
	confA := *a.conf
	confA.RestoreCommittedLogs = true
	fsmA := &MockFSM{}
	restartedA, err := NewRaft(&confA, fsmA, a.logs, a.stable, a.snaps, transA)
	if err != nil {
		t.Fatalf("restart of A failed: %v", err)
	}
	a.raft = restartedA
	a.fsm = fsmA
	defer func() { _ = restartedA.Shutdown().Error() }()
	confsA := assuranceMultiConfigurations(restartedA)

	assuranceMultiEmit(assuranceMultiEvent{
		"event":                  "assurance.vote.restart",
		"node":                   "A",
		"restore_committed_logs": true,
		"staged_commit_index":    staged,
		"premise_filler_applies": extra,
		"latest_config_index":    confsA.latestIndex,
		"latest_config_voters":   assuranceMultiVoters(confsA.latest),
		"group_voters":           len(configuration.Servers),
	})

	// Restart B as well, so that it must campaign and can only win with A's vote.
	if err := b.raft.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown B failed: %v", err)
	}
	_, transB := NewInmemTransport(b.addr)
	transB.Connect(a.addr, transA)
	transA.Connect(b.addr, transB)
	b.trans = transB
	confB := *b.conf
	confB.RestoreCommittedLogs = false
	fsmB := &MockFSM{}
	restartedB, err := NewRaft(&confB, fsmB, b.logs, b.stable, b.snaps, transB)
	if err != nil {
		t.Fatalf("restart of B failed: %v", err)
	}
	b.raft = restartedB
	b.fsm = fsmB
	defer func() { _ = restartedB.Shutdown().Error() }()

	// Sample A's states while B campaigns.
	becameLeader := false
	seen := map[string]int{}
	deadline := time.Now().Add(3 * time.Second)
	for time.Now().Before(deadline) {
		seen[restartedA.State().String()]++
		if restartedB.State() == Leader {
			becameLeader = true
			break
		}
		time.Sleep(5 * time.Millisecond)
	}
	assuranceMultiEmit(assuranceMultiEvent{
		"event":                  "assurance.vote.empty_config",
		"node":                   "A",
		"restore_committed_logs": true,
		"staged_commit_index":    staged,
		"premise_filler_applies": extra,
		"a_latest_config_index":  confsA.latestIndex,
		"a_latest_config_voters": assuranceMultiVoters(confsA.latest),
		"b_became_leader":        becameLeader,
		"b_final_state":          restartedB.State().String(),
		"a_candidate_samples":    seen["Candidate"],
		"a_follower_samples":     seen["Follower"],
		"a_leader_samples":       seen["Leader"],
	})
}

harness.source:
package raft

import (
	"encoding/json"
	"fmt"
	"runtime"
	"sort"
	"strings"
	"testing"
	"time"
)

// TestAssuranceRestoreCommittedLogsConfigurationRecovery
//
// Sourced question: when Config.RestoreCommittedLogs is enabled, does a node that
// restarts on top of its persisted stores still recover the membership configuration
// that its own log already contains?
//
// api.go starts the startup configuration scan at max(snapshotIndex, lastApplied)+1.
// restoreFromCommittedLogs() sets lastApplied to the commit index read from the log
// store before that scan runs, so every configuration entry at an index <= that
// commit index is skipped even though it is present in the node's log.
//
// The harness builds real (bootstrap -> election -> client applies -> shutdown)
// single-voter prefixes on top of a commit-tracking log store, then restarts the node
// with the same stores and a fresh in-memory FSM, once with RestoreCommittedLogs on and
// once with it off, and reports the operands of the recovery.

type assuranceEvent map[string]interface{}

func assuranceEmit(ev assuranceEvent) {
	b, err := json.Marshal(ev)
	if err != nil {
		fmt.Println(`CA_EVENT {"event":"assurance.marshal_error"}`)
		return
	}
	fmt.Println("CA_EVENT " + string(b))
}

type assuranceStores struct {
	addr   ServerAddress
	local  ServerID
	conf   *Config
	logs   *InmemCommitTrackingStore
	stable *InmemStore
	snaps  *InmemSnapshotStore
}

func assuranceWaitElected(t *testing.T, r *Raft, timeout time.Duration) bool {
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		if r.State() == Leader {
			return true
		}
		time.Sleep(5 * time.Millisecond)
	}
	return r.State() == Leader
}

// assuranceBuildPrefix runs the pre-restart life of one node and returns the stores it
// leaves behind. applyAfterSnapshot entries are applied after the optional snapshot, and
// the optional configuration change (AddNonvoter of a peer that never connects) is made
// after that snapshot as well, so the node has a committed configuration entry above its
// newest snapshot.
func assuranceBuildPrefix(t *testing.T, withSnapshot bool, caseName string) *assuranceStores {
	t.Helper()

	addr, trans := NewInmemTransport("")
	local := ServerID("server-" + string(addr))
	conf := inmemConfig(t)
	conf.LocalID = local
	// The prefix must run with the feature enabled, otherwise no commit index is ever
	// staged into the log store and the restart has nothing to read.
	conf.RestoreCommittedLogs = true
	conf.TrailingLogs = 16

	stores := &assuranceStores{
		addr:   addr,
		local:  local,
		conf:   conf,
		logs:   NewInmemCommitTrackingStore(),
		stable: NewInmemStore(),
		snaps:  NewInmemSnapshotStore(),
	}
	configuration := Configuration{Servers: []Server{{
		Suffrage: Voter,
		ID:       local,
		Address:  addr,
	}}}
	if err := BootstrapCluster(conf, stores.logs, stores.stable, stores.snaps, trans, configuration); err != nil {
		t.Fatalf("bootstrap failed: %v", err)
	}

	r, err := NewRaft(conf, &MockFSM{}, stores.logs, stores.stable, stores.snaps, trans)
	if err != nil {
		t.Fatalf("prefix NewRaft failed: %v", err)
	}
	if !assuranceWaitElected(t, r, 3*time.Second) {
		t.Fatalf("prefix node never became leader")
	}

	for i := 0; i < 4; i++ {
		if err := r.Apply([]byte(fmt.Sprintf("pre-%d", i)), 0).Error(); err != nil {
			t.Fatalf("prefix apply failed: %v", err)
		}
	}

	if withSnapshot {
		if err := r.Snapshot().Error(); err != nil {
			t.Fatalf("prefix snapshot failed: %v", err)
		}
		// A committed configuration entry strictly above the snapshot index.
		f := r.AddNonvoter(ServerID("assurance-peer-2"), ServerAddress("assurance-peer-2-addr"), 0, 2*time.Second)
		if err := f.Error(); err != nil {
			t.Fatalf("prefix AddNonvoter failed: %v", err)
		}
		for i := 0; i < 2; i++ {
			if err := r.Apply([]byte(fmt.Sprintf("post-%d", i)), 0).Error(); err != nil {
				t.Fatalf("prefix post apply failed: %v", err)
			}
		}
	}

	// Record the persisted state before shutdown.
	stagedCommit, err := stores.logs.GetCommitIndex()
	if err != nil {
		t.Fatalf("GetCommitIndex failed: %v", err)
	}
	lastIndex, err := stores.logs.LastIndex()
	if err != nil {
		t.Fatalf("LastIndex failed: %v", err)
	}
	configs, err := assuranceLogConfigEntries(stores.logs, lastIndex)
	if err != nil {
		t.Fatalf("log scan failed: %v", err)
	}
	snapIndex, snapTerm := r.getLastSnapshot()
	assuranceEmit(assuranceEvent{
		"event":                 "assurance.prefix",
		"case":                  caseName,
		"snapshot_present":      withSnapshot,
		"snapshot_index":        snapIndex,
		"snapshot_term":         snapTerm,
		"log_last_index":        lastIndex,
		"staged_commit_index":   stagedCommit,
		"config_entries":        configs.summary,
		"last_config_index":     configs.lastIndex,
		"last_config_voters":    configs.lastVoters,
		"last_config_nonvoters": configs.lastNonvoters,
		"recording_label_count": 0,
	})

	if err := r.Shutdown().Error(); err != nil {
		t.Fatalf("prefix shutdown failed: %v", err)
	}
	return stores
}

type assuranceConfigScan struct {
	summary       string
	lastIndex     uint64
	lastVoters    int
	lastNonvoters int
	lastIDs       []string
}

func assuranceLogConfigEntries(logs *InmemCommitTrackingStore, lastIndex uint64) (assuranceConfigScan, error) {
	out := assuranceConfigScan{summary: ""}
	for idx := uint64(1); idx <= lastIndex; idx++ {
		var entry Log
		if err := logs.GetLog(idx, &entry); err != nil {
			return out, err
		}
		switch entry.Type {
		case LogConfiguration:
			conf := DecodeConfiguration(entry.Data)
			voters, nonvoters := assuranceSuffrageCounts(conf)
			out.summary += fmt.Sprintf("LogConfiguration@%d(servers=%d,voters=%d)", idx, len(conf.Servers), voters)
			out.lastIndex = idx
			out.lastVoters = voters
			out.lastNonvoters = nonvoters
			out.lastIDs = assuranceSortedIDs(conf)
		case LogAddPeerDeprecated, LogRemovePeerDeprecated:
			out.summary += fmt.Sprintf("DeprecatedPeers@%d", idx)
			out.lastIndex = idx
		}
	}
	return out, nil
}

func assuranceSuffrageCounts(conf Configuration) (voters, nonvoters int) {
	for _, s := range conf.Servers {
		if s.Suffrage == Voter {
			voters++
		} else {
			nonvoters++
		}
	}
	return voters, nonvoters
}

func assuranceConfigIDs(conf Configuration) string {
	out := ""
	for i, s := range conf.Servers {
		if i > 0 {
			out += ","
		}
		out += string(s.ID)
	}
	return out
}

// assuranceSortedIDs returns a comparable, order independent list of server IDs.
func assuranceSortedIDs(conf Configuration) []string {
	out := make([]string, 0, len(conf.Servers))
	for _, s := range conf.Servers {
		out = append(out, string(s.ID))
	}
	sort.Strings(out)
	return out
}

// assuranceConfigurations asks the node's main thread for its current view of the
// tracked configurations, mirroring the pattern used by takeSnapshot.
func assuranceConfigurations(r *Raft) configurations {
	fut := &configurationsFuture{}
	fut.ShutdownCh = r.shutdownCh
	fut.init()
	select {
	case r.configurationsCh <- fut:
	case <-r.shutdownCh:
		return configurations{}
	}
	if err := fut.Error(); err != nil {
		return configurations{}
	}
	return fut.configurations
}

// assuranceRunCase restarts the node on top of the stored prefix and reports what the
// recovered node does with its configuration.
func assuranceRunCase(t *testing.T, caseName string, withSnapshot, restoreCommittedLogs bool) {
	t.Helper()

	stores := assuranceBuildPrefix(t, withSnapshot, caseName)
	stagedCommit, err := stores.logs.GetCommitIndex()
	if err != nil {
		t.Fatalf("GetCommitIndex failed: %v", err)
	}
	lastIndex, err := stores.logs.LastIndex()
	if err != nil {
		t.Fatalf("LastIndex failed: %v", err)
	}
	logConfigs, err := assuranceLogConfigEntries(stores.logs, lastIndex)
	if err != nil {
		t.Fatalf("log scan failed: %v", err)
	}

	// The fresh transport keeps the node's address (and therefore its ID) stable.
	_, trans := NewInmemTransport(stores.addr)
	conf := *stores.conf
	conf.RestoreCommittedLogs = restoreCommittedLogs

	assuranceEmit(assuranceEvent{
		"event":                   "assurance.restart." + caseName,
		"case":                    caseName,
		"restore_committed_logs":  restoreCommittedLogs,
		"snapshot_present":        withSnapshot,
		"log_last_index":          lastIndex,
		"staged_commit_index":     stagedCommit,
		"log_last_config_index":   logConfigs.lastIndex,
		"log_last_config_voters":  logConfigs.lastVoters,
		"log_last_config_servers": logConfigs.lastVoters + logConfigs.lastNonvoters,
	})

	r, err := NewRaft(&conf, &MockFSM{}, stores.logs, stores.stable, stores.snaps, trans)
	if err != nil {
		assuranceEmit(assuranceEvent{
			"event":                  "assurance.outcome." + caseName,
			"case":                   caseName,
			"restore_committed_logs": restoreCommittedLogs,
			"snapshot_present":       withSnapshot,
			"new_raft_error":         err.Error(),
		})
		return
	}

	// Observation window: 1.5s is 30 election/heartbeat timeouts of this in-memory
	// configuration (HeartbeatTimeout = ElectionTimeout = 50ms).
	deadline := time.Now().Add(1500 * time.Millisecond)
	leaderObserved := false
	polls := 0
	for time.Now().Before(deadline) {
		polls++
		if r.State() == Leader {
			leaderObserved = true
			break
		}
		time.Sleep(5 * time.Millisecond)
	}

	snapIndex, _ := r.getLastSnapshot()
	lastApplied := r.AppliedIndex()
	leaderAddr, leaderID := r.LeaderWithID()

	// Ask the main thread for the configuration the node is actually tracking.
	confs := assuranceConfigurations(r)
	latestVoters, latestNonvoters := assuranceSuffrageCounts(confs.latest)
	committedVoters, committedNonvoters := assuranceSuffrageCounts(confs.committed)
	latestIDs := assuranceSortedIDs(confs.latest)
	logIDs := logConfigs.lastIDs
	sameMembership := len(latestIDs) == len(logIDs)
	if sameMembership {
		for i := range latestIDs {
			if latestIDs[i] != logIDs[i] {
				sameMembership = false
				break
			}
		}
	}

	assuranceEmit(assuranceEvent{
		"event":                      "assurance.outcome." + caseName,
		"case":                       caseName,
		"restore_committed_logs":     restoreCommittedLogs,
		"snapshot_present":           withSnapshot,
		"leader_observed":            leaderObserved,
		"final_state":                r.State().String(),
		"polls":                      polls,
		"observation_ms":             1500,
		"leader_id":                  string(leaderID),
		"leader_addr":                string(leaderAddr),
		"latest_config_index":        confs.latestIndex,
		"committed_config_index":     confs.committedIndex,
		"latest_config_voters":       latestVoters,
		"latest_config_nonvoters":    latestNonvoters,
		"latest_config_ids":          assuranceConfigIDs(confs.latest),
		"committed_config_voters":    committedVoters,
		"committed_config_ids":       assuranceConfigIDs(confs.committed),
		"snapshot_index":             snapIndex,
		"last_applied":               lastApplied,
		"commit_index":               r.CommitIndex(),
		"last_index":                 r.LastIndex(),
		"committed_config_nonvoters": committedNonvoters,
	})

	// Does the recovered configuration equal the newest configuration entry in the
	// node's own log? Both operands are reported above; this flag is the comparison.
	matches := logConfigs.lastIndex != 0 &&
		sameMembership &&
		latestVoters == logConfigs.lastVoters &&
		latestNonvoters == logConfigs.lastNonvoters
	assuranceEmit(assuranceEvent{
		"event":                          "assurance.config_recovery." + caseName,
		"case":                           caseName,
		"restore_committed_logs":         restoreCommittedLogs,
		"snapshot_present":               withSnapshot,
		"log_last_config_index":          logConfigs.lastIndex,
		"log_last_config_voters":         logConfigs.lastVoters,
		"log_last_config_nonvoters":      logConfigs.lastNonvoters,
		"log_last_config_ids":            strings.Join(logConfigs.lastIDs, ","),
		"latest_config_index":            confs.latestIndex,
		"latest_config_voters":           latestVoters,
		"latest_config_nonvoters":        latestNonvoters,
		"latest_config_ids":              strings.Join(latestIDs, ","),
		"config_matches_last_log_config": matches,
	})

	_ = r.Shutdown().Error()
}

func TestAssuranceRestoreCommittedLogsConfigurationRecovery(t *testing.T) {
	assuranceRunCase(t, "no_snapshot_restore_on", false, true)
	assuranceRunCase(t, "no_snapshot_restore_off", false, false)
	assuranceRunCase(t, "snapshot_then_config_restore_on", true, true)
	assuranceRunCase(t, "snapshot_then_config_restore_off", true, false)
}

// TestAssuranceRestoreCommittedLogsReplayCompletion
//
// Sourced question: does the startup replay performed by restoreFromCommittedLogs
// always complete? processLogs hands batches to the FSM through a buffered channel
// whose only consumer (runFSM) is started at the end of NewRaft, and the send has no
// timeout: it waits for buffer space or shutdown. So a replay that needs more batches
// than the channel can hold blocks inside NewRaft, before the consumer exists.
//
// The harness builds prefixes whose committed log is far above their (absent)
// snapshot, restarts them with and without RestoreCommittedLogs, and reports whether
// NewRaft returned and what the blocked goroutine was doing.

func assuranceBuildReplayPrefix(t *testing.T, caseName string, entries, maxAppendEntries int) *assuranceStores {
	t.Helper()

	addr, trans := NewInmemTransport("")
	local := ServerID("server-" + string(addr))
	conf := inmemConfig(t)
	conf.LocalID = local
	conf.RestoreCommittedLogs = true
	// Keep the whole committed log above the snapshot: no automatic snapshot is taken,
	// so a restart replays every committed entry from index 1.
	conf.SnapshotThreshold = 1 << 30
	conf.SnapshotInterval = time.Hour
	conf.MaxAppendEntries = maxAppendEntries

	stores := &assuranceStores{
		addr:   addr,
		local:  local,
		conf:   conf,
		logs:   NewInmemCommitTrackingStore(),
		stable: NewInmemStore(),
		snaps:  NewInmemSnapshotStore(),
	}
	configuration := Configuration{Servers: []Server{{
		Suffrage: Voter,
		ID:       local,
		Address:  addr,
	}}}
	if err := BootstrapCluster(conf, stores.logs, stores.stable, stores.snaps, trans, configuration); err != nil {
		t.Fatalf("bootstrap failed: %v", err)
	}
	r, err := NewRaft(conf, &MockFSM{}, stores.logs, stores.stable, stores.snaps, trans)
	if err != nil {
		t.Fatalf("prefix NewRaft failed: %v", err)
	}
	if !assuranceWaitElected(t, r, 3*time.Second) {
		t.Fatalf("prefix node never became leader")
	}
	for i := 0; i < entries; i++ {
		if err := r.Apply([]byte("x"), 0).Error(); err != nil {
			t.Fatalf("prefix apply %d failed: %v", i, err)
		}
	}
	staged, err := stores.logs.GetCommitIndex()
	if err != nil {
		t.Fatalf("GetCommitIndex failed: %v", err)
	}
	lastIndex, err := stores.logs.LastIndex()
	if err != nil {
		t.Fatalf("LastIndex failed: %v", err)
	}
	snapIndex, _ := r.getLastSnapshot()
	assuranceEmit(assuranceEvent{
		"event":               "assurance.replay_prefix",
		"case":                caseName,
		"commands_applied":    entries,
		"log_last_index":      lastIndex,
		"staged_commit_index": staged,
		"snapshot_index":      snapIndex,
		"max_append_entries":  conf.MaxAppendEntries,
		"replay_entries":      staged - snapIndex,
		"replay_batches":      (staged - snapIndex + uint64(conf.MaxAppendEntries) - 1) / uint64(conf.MaxAppendEntries),
	})
	if err := r.Shutdown().Error(); err != nil {
		t.Fatalf("prefix shutdown failed: %v", err)
	}
	return stores
}

// assuranceStackExcerpt returns the goroutine block that mentions marker.
func assuranceStackExcerpt(text string, marker string) (string, int) {
	count := strings.Count(text, marker)
	if count == 0 {
		return "", 0
	}
	idx := strings.Index(text, marker)
	start := idx - 200
	if start < 0 {
		start = 0
	}
	end := idx + 300
	if end > len(text) {
		end = len(text)
	}
	excerpt := strings.ReplaceAll(text[start:end], "\n", " | ")
	return excerpt, count
}

type assuranceReplayResult struct {
	raft     *Raft
	err      error
	elapsed  int64
	returned bool
}

func assuranceRunReplayCase(t *testing.T, caseName string, restoreCommittedLogs bool, entries, maxAppendEntries int) {
	t.Helper()

	stores := assuranceBuildReplayPrefix(t, caseName, entries, maxAppendEntries)
	staged, err := stores.logs.GetCommitIndex()
	if err != nil {
		t.Fatalf("GetCommitIndex failed: %v", err)
	}
	lastIndex, err := stores.logs.LastIndex()
	if err != nil {
		t.Fatalf("LastIndex failed: %v", err)
	}
	_, trans := NewInmemTransport(stores.addr)
	conf := *stores.conf
	conf.RestoreCommittedLogs = restoreCommittedLogs

	assuranceEmit(assuranceEvent{
		"event":                  "assurance.replay_restart." + caseName,
		"case":                   caseName,
		"restore_committed_logs": restoreCommittedLogs,
		"staged_commit_index":    staged,
		"log_last_index":         lastIndex,
		"max_append_entries":     conf.MaxAppendEntries,
		"replay_entries":         staged,
	})

	const waitMS = 8000
	ch := make(chan assuranceReplayResult, 1)
	go func() {
		start := time.Now()
		r, err := NewRaft(&conf, &MockFSM{}, stores.logs, stores.stable, stores.snaps, trans)
		ch <- assuranceReplayResult{raft: r, err: err, elapsed: time.Since(start).Milliseconds(), returned: true}
	}()

	var res assuranceReplayResult
	select {
	case res = <-ch:
	case <-time.After(waitMS * time.Millisecond):
	}

	outcome := assuranceEvent{
		"event":                  "assurance.replay_outcome." + caseName,
		"case":                   caseName,
		"restore_committed_logs": restoreCommittedLogs,
		"new_raft_returned":      res.returned,
		"wait_ms":                waitMS,
	}
	if res.returned {
		outcome["elapsed_ms"] = res.elapsed
	}
	if res.err != nil {
		outcome["new_raft_error"] = res.err.Error()
	}
	if !res.returned {
		buf := make([]byte, 1<<20)
		n := runtime.Stack(buf, true)
		excerpt, count := assuranceStackExcerpt(string(buf[:n]), "restoreFromCommittedLogs")
		outcome["stack_mentions"] = count
		outcome["blocked_excerpt"] = excerpt
	}
	assuranceEmit(outcome)

	if res.returned && res.raft != nil {
		leaderObserved := assuranceWaitElected(t, res.raft, time.Second)
		assuranceEmit(assuranceEvent{
			"event":                  "assurance.replay_leadership." + caseName,
			"case":                   caseName,
			"restore_committed_logs": restoreCommittedLogs,
			"leader_observed":        leaderObserved,
			"final_state":            res.raft.State().String(),
			"last_applied":           res.raft.AppliedIndex(),
			"commit_index":           res.raft.CommitIndex(),
		})
		_ = res.raft.Shutdown().Error()
	}
}

func TestAssuranceRestoreCommittedLogsReplayCompletion(t *testing.T) {
	const entries = 9000
	assuranceRunReplayCase(t, "large_replay_restore_on", true, entries, 64)
	assuranceRunReplayCase(t, "large_replay_restore_off", false, entries, 64)
}

// TestAssuranceRestoreCommittedLogsReplayBound
//
// Sourced question: does the completion of the startup replay track the product of the
// batch size and the channel capacity, rather than the amount of log alone? The replay
// delivers batches of at most config.MaxAppendEntries into a channel of capacity 128, so
// the number of batches is ceil(replay/MaxAppendEntries) and the bound sits at
// 128*MaxAppendEntries entries. This runs the same flag-on restart with a smaller legal
// MaxAppendEntries, once below that bound and once above it.
func TestAssuranceRestoreCommittedLogsReplayBound(t *testing.T) {
	const maxAppendEntries = 16 // bound: 128 * 16 = 2048 replayed entries
	assuranceRunReplayCase(t, "bound16_below_replay_on", true, 1500, maxAppendEntries)
	assuranceRunReplayCase(t, "bound16_above_replay_on", true, 3000, maxAppendEntries)
}

// assuranceTupleCount counts the entries in (from, to] that processLogs turns into commit
// tuples for the default protocol version: commands, barriers and configuration entries.
// No-op entries (and deprecated peer entries, and configuration entries below protocol 3)
// produce no tuple and therefore consume no batch space.
func assuranceTupleCount(logs *InmemCommitTrackingStore, from, to uint64) int {
	count := 0
	for idx := from + 1; idx <= to; idx++ {
		var entry Log
		if err := logs.GetLog(idx, &entry); err != nil {
			return count
		}
		switch entry.Type {
		case LogCommand, LogBarrier, LogConfiguration:
			count++
		}
	}
	return count
}

// assuranceBuildReplayPrefixToTarget builds a prefix whose persisted commit index is the
// given target, so a restart's replay batch count can be placed exactly on a boundary.
func assuranceBuildReplayPrefixToTarget(t *testing.T, caseName string, target uint64, maxAppendEntries int) *assuranceStores {
	t.Helper()

	addr, trans := NewInmemTransport("")
	local := ServerID("server-" + string(addr))
	conf := inmemConfig(t)
	conf.LocalID = local
	conf.RestoreCommittedLogs = true
	conf.SnapshotThreshold = 1 << 30
	conf.SnapshotInterval = time.Hour
	conf.MaxAppendEntries = maxAppendEntries

	stores := &assuranceStores{
		addr:   addr,
		local:  local,
		conf:   conf,
		logs:   NewInmemCommitTrackingStore(),
		stable: NewInmemStore(),
		snaps:  NewInmemSnapshotStore(),
	}
	configuration := Configuration{Servers: []Server{{
		Suffrage: Voter,
		ID:       local,
		Address:  addr,
	}}}
	if err := BootstrapCluster(conf, stores.logs, stores.stable, stores.snaps, trans, configuration); err != nil {
		t.Fatalf("bootstrap failed: %v", err)
	}
	r, err := NewRaft(conf, &MockFSM{}, stores.logs, stores.stable, stores.snaps, trans)
	if err != nil {
		t.Fatalf("prefix NewRaft failed: %v", err)
	}
	if !assuranceWaitElected(t, r, 3*time.Second) {
		t.Fatalf("prefix node never became leader")
	}

	applied := 0
	staged, _ := stores.logs.GetCommitIndex()
	for staged < target && applied < int(target)+64 {
		if err := r.Apply([]byte("x"), 0).Error(); err != nil {
			t.Fatalf("prefix apply %d failed: %v", applied, err)
		}
		applied++
		staged, _ = stores.logs.GetCommitIndex()
	}
	lastIndex, err := stores.logs.LastIndex()
	if err != nil {
		t.Fatalf("LastIndex failed: %v", err)
	}
	snapIndex, _ := r.getLastSnapshot()
	assuranceEmit(assuranceEvent{
		"event":               "assurance.boundary.prefix." + caseName,
		"case":                caseName,
		"commands_applied":    applied,
		"target_replay":       target,
		"log_last_index":      lastIndex,
		"staged_commit_index": staged,
		"snapshot_index":      snapIndex,
		"max_append_entries":  maxAppendEntries,
		"replay_entries":      staged - snapIndex,
		"replay_batches":      (staged - snapIndex + uint64(maxAppendEntries) - 1) / uint64(maxAppendEntries),
		"delivered_tuples":    assuranceTupleCount(stores.logs, snapIndex, staged),
		"delivered_batches":   (assuranceTupleCount(stores.logs, snapIndex, staged) + maxAppendEntries - 1) / maxAppendEntries,
	})
	if err := r.Shutdown().Error(); err != nil {
		t.Fatalf("prefix shutdown failed: %v", err)
	}
	return stores
}

// TestAssuranceRestoreCommittedLogsReplayBoundary places the flag-on replay on the two sides
// of the 128-batch channel capacity at MaxAppendEntries 16. The batch count follows the entries
// that processLogs turns into commit tuples (commands, configuration entries, barriers), not
// every log entry, so the two targets were chosen from an observed run of the same harness:
// a replay ending at index 2049 returned and one ending at 2050 is expected to block.
func TestAssuranceRestoreCommittedLogsReplayBoundary(t *testing.T) {
	// Each entry pairs a batch size with the two staged commit indices that straddle the
	// channel's capacity at that size: 128 batches times MaxAppendEntries, plus the single
	// no-op in the replayed range, which produces no commit tuple.
	cases := []struct {
		maxAppendEntries uint64
		target           uint64
	}{
		{16, 2049}, {16, 2050},
		{64, 8193}, {64, 8194},
	}
	for _, c := range cases {
		maxAppendEntries := int(c.maxAppendEntries)
		target := c.target
		caseName := fmt.Sprintf("boundary_%d_batch%d", target, maxAppendEntries)
		stores := assuranceBuildReplayPrefixToTarget(t, caseName, target, maxAppendEntries)
		staged, _ := stores.logs.GetCommitIndex()
		_, trans := NewInmemTransport(stores.addr)
		conf := *stores.conf
		conf.RestoreCommittedLogs = true

		assuranceEmit(assuranceEvent{
			"event":                  "assurance.boundary.restart." + caseName,
			"case":                   caseName,
			"restore_committed_logs": true,
			"max_append_entries":     maxAppendEntries,
			"replay_entries":         staged,
			"replay_batches":         (staged + uint64(maxAppendEntries) - 1) / uint64(maxAppendEntries),
			"delivered_tuples":       assuranceTupleCount(stores.logs, 0, staged),
			"delivered_batches":      (assuranceTupleCount(stores.logs, 0, staged) + maxAppendEntries - 1) / maxAppendEntries,
		})

		ch := make(chan assuranceReplayResult, 1)
		go func() {
			start := time.Now()
			r, err := NewRaft(&conf, &MockFSM{}, stores.logs, stores.stable, stores.snaps, trans)
			ch <- assuranceReplayResult{raft: r, err: err, elapsed: time.Since(start).Milliseconds(), returned: true}
		}()
		const waitMS = 8000
		var res assuranceReplayResult
		select {
		case res = <-ch:
		case <-time.After(waitMS * time.Millisecond):
		}
		outcome := assuranceEvent{
			"event":                  "assurance.boundary.outcome." + caseName,
			"case":                   caseName,
			"restore_committed_logs": true,
			"max_append_entries":     maxAppendEntries,
			"new_raft_returned":      res.returned,
			"wait_ms":                waitMS,
		}
		if res.returned {
			outcome["elapsed_ms"] = res.elapsed
		} else {
			buf := make([]byte, 1<<20)
			n := runtime.Stack(buf, true)
			excerpt, mentions := assuranceStackExcerpt(string(buf[:n]), "restoreFromCommittedLogs")
			outcome["stack_mentions"] = mentions
			outcome["blocked_excerpt"] = excerpt
		}
		assuranceEmit(outcome)
		if res.returned && res.raft != nil {
			_ = res.raft.Shutdown().Error()
		}
	}
}

// TestAssuranceRestoreCommittedLogsDefaultConfiguration
//
// Sourced question: does the replay bound depend on tuning SnapshotThreshold or
// MaxAppendEntries, or is it reachable with the library's own defaults? This harness
// builds single-voter prefixes with DefaultConfig untouched except for the replay flag
// and short node timeouts (SnapshotThreshold 8192, MaxAppendEntries 64, SnapshotInterval
// 120s), applies commands until the committed range above the newest snapshot passes the
// bound, and restarts the node with the replay on and off.
func assuranceRunDefaultConfigCase(t *testing.T, caseName string, restoreCommittedLogs bool, commands int) {
	t.Helper()

	addr, trans := NewInmemTransport("")
	local := ServerID("server-" + string(addr))
	conf := inmemConfig(t)
	conf.LocalID = local
	conf.RestoreCommittedLogs = true

	stores := &assuranceStores{
		addr:   addr,
		local:  local,
		conf:   conf,
		logs:   NewInmemCommitTrackingStore(),
		stable: NewInmemStore(),
		snaps:  NewInmemSnapshotStore(),
	}
	configuration := Configuration{Servers: []Server{{
		Suffrage: Voter,
		ID:       local,
		Address:  addr,
	}}}
	if err := BootstrapCluster(conf, stores.logs, stores.stable, stores.snaps, trans, configuration); err != nil {
		t.Fatalf("bootstrap failed: %v", err)
	}
	r, err := NewRaft(conf, &MockFSM{}, stores.logs, stores.stable, stores.snaps, trans)
	if err != nil {
		t.Fatalf("prefix NewRaft failed: %v", err)
	}
	if !assuranceWaitElected(t, r, 3*time.Second) {
		t.Fatalf("prefix node never became leader")
	}
	for i := 0; i < commands; i++ {
		if err := r.Apply([]byte("x"), 0).Error(); err != nil {
			t.Fatalf("prefix apply %d failed: %v", i, err)
		}
	}
	staged, _ := stores.logs.GetCommitIndex()
	lastIndex, _ := stores.logs.LastIndex()
	snapIndex, _ := r.getLastSnapshot()
	snapList, _ := stores.snaps.List()
	bound := uint64(128 * conf.MaxAppendEntries)
	delta := staged - snapIndex
	assuranceEmit(assuranceEvent{
		"event":                    "assurance.defaultcfg.prefix." + caseName,
		"case":                     caseName,
		"commands_applied":         commands,
		"log_last_index":           lastIndex,
		"staged_commit_index":      staged,
		"snapshot_index":           snapIndex,
		"snapshots_listed":         len(snapList),
		"max_append_entries":       conf.MaxAppendEntries,
		"snapshot_threshold":       conf.SnapshotThreshold,
		"snapshot_interval_s":      conf.SnapshotInterval.Seconds(),
		"committed_above_snapshot": delta,
		"bound_entries":            bound,
		"delta_exceeds_bound":      delta > bound,
	})
	if err := r.Shutdown().Error(); err != nil {
		t.Fatalf("prefix shutdown failed: %v", err)
	}

	_, trans2 := NewInmemTransport(stores.addr)
	conf2 := *stores.conf
	conf2.RestoreCommittedLogs = restoreCommittedLogs
	assuranceEmit(assuranceEvent{
		"event":                  "assurance.defaultcfg.restart." + caseName,
		"case":                   caseName,
		"restore_committed_logs": restoreCommittedLogs,
		"max_append_entries":     conf2.MaxAppendEntries,
		"snapshot_threshold":     conf2.SnapshotThreshold,
		"replay_entries":         delta,
		"replay_batches":         (delta + uint64(conf2.MaxAppendEntries) - 1) / uint64(conf2.MaxAppendEntries),
		"delta_exceeds_bound":    delta > bound,
	})

	ch := make(chan assuranceReplayResult, 1)
	go func() {
		start := time.Now()
		r2, err := NewRaft(&conf2, &MockFSM{}, stores.logs, stores.stable, stores.snaps, trans2)
		ch <- assuranceReplayResult{raft: r2, err: err, elapsed: time.Since(start).Milliseconds(), returned: true}
	}()
	const waitMS = 8000
	var res assuranceReplayResult
	select {
	case res = <-ch:
	case <-time.After(waitMS * time.Millisecond):
	}
	outcome := assuranceEvent{
		"event":                  "assurance.defaultcfg.outcome." + caseName,
		"case":                   caseName,
		"restore_committed_logs": restoreCommittedLogs,
		"max_append_entries":     conf2.MaxAppendEntries,
		"snapshot_threshold":     conf2.SnapshotThreshold,
		"replay_entries":         delta,
		"delta_exceeds_bound":    delta > bound,
		"new_raft_returned":      res.returned,
		"wait_ms":                waitMS,
	}
	if res.returned {
		outcome["elapsed_ms"] = res.elapsed
	} else {
		buf := make([]byte, 1<<20)
		n := runtime.Stack(buf, true)
		excerpt, mentions := assuranceStackExcerpt(string(buf[:n]), "restoreFromCommittedLogs")
		outcome["stack_mentions"] = mentions
		outcome["blocked_excerpt"] = excerpt
	}
	assuranceEmit(outcome)
	if res.returned && res.raft != nil {
		_ = res.raft.Shutdown().Error()
	}
}

func TestAssuranceRestoreCommittedLogsDefaultConfiguration(t *testing.T) {
	const commands = 12000
	assuranceRunDefaultConfigCase(t, "default_config_replay_on", true, commands)
	assuranceRunDefaultConfigCase(t, "default_config_replay_off", false, commands)
}

